{"cmd": "cat > evidence.json << 'EOF'
{
  "case": "spider2lite_f1_overtake_audit_hard",
  "source_tables": {
    "lap_positions": "race_id, driver_id, lap, position, lap_type — eligible rows: lap_type = 'Race', lap >= 1",
    "results": "race_id, driver_id, grid — grid positions used as previous state for lap 1. Duplicates resolved with MAX(grid) GROUP BY (race_id, driver_id) WHERE grid > 0",
    "races_ext": "race_id, is_pit_data_available — defines Part A scope (is_pit_data_available = 1, 273 races)",
    "pit_stops": "race_id, driver_id, lap — used for P classification (pit entry on event lap, pit exit on lap-1)",
    "retirements": "race_id, driver_id, lap — used for R classification (overtaken_driver retired on event lap)",
    "drivers": "driver_id, forename, surname — used for Part C full names"
  },
  "event_construction": {
    "eligible_rows": "lap_positions WHERE lap_type = 'Race' AND lap >= 1. Retirement-prefixed lap_type rows ('Retirement (Mechanical Problem)', 'Retirement (Driver Error)', 'Retirement (Disqualification)') are excluded from event construction.",
    "lap_0_exclusion": "lap = 0 rows are starting-position records, not compared to lap 1.",
    "lap_1_previous_state": "results.grid (one value per race_id + driver_id, grid > 0). Drivers without a grid value are excluded from lap 1 events.",
    "lap_n_previous_state": "lap_positions for lap n-1 with lap_type = 'Race', same race_id.",
    "direction": "If driver A was ahead of B in previous state (lower position number), and A is behind B in current state, then B overtook A. Event lap = current lap, overtaking_driver = B, overtaken_driver = A.",
    "pairwise": "All driver pairs present in both previous and current states are compared. If either driver is missing from either state, no event is formed for that pair and lap."
  },
  "classification": {
    "priority_order": "R, then P, then S, then T. First matching rule wins.",
    "R_retirement": "overtaken_driver has a row in retirements for the same race_id and event lap.",
    "P_pit": "overtaken_driver has a row in pit_stops for the same race_id AND (event lap OR event lap - 1). Pit entry = pit stop on event lap. Pit exit = pit stop on lap immediately before event lap.",
    "S_start": "event lap is 1, both drivers have results.grid values, and abs(grid_overtaker - grid_overtaken) <= 2.",
    "T_track": "fallback — event does not match R, P, or S."
  },
  "part_scopes": {
    "part_a": "All races where races_ext.is_pit_data_available = 1 (273 races, IDs 841–1132). All eligible race laps in those races.",
    "part_b": "All races (531 with lap_type='Race' data). Only events with event lap 1 through 5.",
    "part_c": "All races, all eligible race laps. Only events classified as T after R/P/S/T priority. Count overtook (as overtaking_driver) and was_overtaken (as overtaken_driver) per driver. Output drivers where was_overtaken > overtook."
  },
  "part_c_direction": "For each T event, overtaking_driver gets +1 overtook, overtaken_driver gets +1 was_overtaken. Drivers with was_overtaken > overtook are listed in track_deficit_drivers.csv, sorted by driver_id."
}
EOF"}
